 i zdrave grickalice, dostupne su na na\\u0161oj online platformi.<\\/p>\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"rem\",\"size\":1},\"typography_line_height\":{\"unit\":\"em\",\"size\":1.7},\"text_color\":\"#757575\",\"typography_font_family\":\"Nunito\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"3c716435\",\"elType\":\"widget\",\"settings\":{\"text\":\"Saznaj vi\\u0161e\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Nunito\",\"typography_font_weight\":\"400\",\"background_color\":\"rgba(255,171,0,0)\",\"hover_color\":\"#ffffff\",\"button_background_hover_color\":\"#ffab00\",\"border_border\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"border_color\":\"#ffab00\",\"border_radius\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"align_tablet\":\"center\",\"typography_font_size\":{\"unit\":\"em\",\"size\":1.1},\"button_text_color\":\"#ffab00\",\"button_hover_border_color\":\"#ffab00\",\"link\":{\"url\":\"http:\\/\\/localhost\\/sajt\\/prodavnica\\/\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},\"elements\":[],\"widgetType\":\"button\"}],\"isInner\":true},{\"id\":\"195e187e\",\"elType\":\"column\",\"settings\":{\"_column_size\":33,\"_inline_size\":null,\"background_background\":\"classic\",\"margin\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true},\"padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true},\"_inline_size_tablet\":50,\"margin_tablet\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"0\",\"isLinked\":false},\"margin_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"border_border\":\"solid\",\"bo