n				text-align:left;\r\n			}\r\n			\r\n			h5, .h5{\r\n				color:#333333 !important;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n			\r\n			div{\r\n				color:#666666 !important;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n\r\n			@media screen and (max-width: 768px) {\r\n				img {max-width:  100% !important; height:  auto; }\r\n				.padded {padding-left:  10px; padding-right: 10px;}\r\n				.nav-inner td {\r\n					display: inline-block;\r\n				}\r\n			}\r\n\r\n			@media screen and (max-width: 320px) {\r\n				.inner {padding-left: 0px !important;padding-right: 0px !important;}\r\n\r\n			}\r\n\r\n			@media screen and (max-width: 610px) {\r\n				table.social > tbody > tr > td {\r\n					display: block;\r\n				}\r\n				.content {padding: 15px 0;}\r\n				table {width: 100%;}\r\n			}\r\n\r\n			@media screen and (max-width: 610px) {\r\n				img {\r\n					width: 100% !important;\r\n					object-fit: contain;\r\n				}\r\n\r\n				td {\r\n					width: 100% !important;\r\n				}\r\n\r\n				table#templateFooter {\r\n					width: 100% !important;\r\n				}\r\n			}\r\n\r\n   </style>\r\n\r\n</head>\r\n    <body style=\"background-color:#EEEEEE;\" leftmargin=\"0\" marginwidth=\"0\" topmargin=\"0\" marginheight=\"0\" offset=\"0\">\r\n    	[newsletters_track]\r\n    	<center>\r\n        	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" height=\"100%\" width=\"100%\" style=\"background:#EEEEEE;\" id=\"backgroundTable\">\r\n            	<tr>\r\n                	<td align=\"center\" valign=\"top\">\r\n					\r\n						<!-- BEGIN TOP SECTION -->\r\n                        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"580\" style=\"background:#EEEEEE;\">\r\n                            <tr>\r\n                                <td valign=\"top\">\r\n                                    <table border=\"0\" cellpadding=\"15\" cellspacing=\"0\" width=\"580\">\r\n                                    	<tr>\r\n                                        	<td valign=\"top\">\r\n                                            	<div style=\"color:#000 !important; font-size:10px; line-height:16px; font-family:Arial, sans-serif;\">\r\n														<p>\r\n															You\'re receiving this newsletter because you subscribed to our mailing list.<br />\r\n															Not interested anymore? [newsletters_unsubscribe]. <br/>\r\n															Having trouble viewing this email? [newsletters_online].\r\n														</p>\r\n                                                </div>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n                        </table>\r\n						<!-- END TOP SECTION -->\r\n						\r\n						<!-- BEGIN CONTENT SECTION -->\r\n                    	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"580\" style=\"background:#FFFFFF;\">\r\n						\r\n							<!-- BEGIN HEADER SECTION -->\r\n                        	<tr>\r\n                            	<td style=\"background-color:#FFFFFF;\" align=\"center\" valign=\"bottom\">\r\n									<img src=\"[newsletters_pluginurl]/includes/themes/redray/images/header.gif\" alt=\"Header\" width=\"600\" height=\"150\" />\r\n                                </td>\r\n                            </tr>\r\n							<!-- END HEADER SECTION -->\r\n							\r\n							<!-- BEGIN TEXT SECTION -->\r\n                        	<tr>\r\n                            	<td valign=\"top\" align=\"center\">\r\n                                    <table border=\"0\" cellspacing=\"0\" width=\"560\">\r\n                                    	<tr>\r\n                                        	<td valign=\"top\">\r\n                                            	<div style=\"color:#333; font-size:14px; line-height:21px; font-family:Helvetica, Arial, sans-serif;\">												   \r\n												   <h2 style=\"color:#680606 !important;\">[newsletters_subject]</h2>\r\n												   [newsletters_main_content]\r\n												   <br />\r\n												   <br />\r\n												</div>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END TEXT SECTION -->\r\n						</table>\r\n						<!-- END CONTENT SECTION -->\r\n						<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n							<!-- BEGIN FOOTER SECTION -->\r\n                        	<tr>\r\n                            	<td	align=\"center\" valign=\"top\">\r\n                                    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\">\r\n                                    	<tr>\r\n                                        	<td align=\"left\" valign=\"middle\" style=\"background:#333333; padding: 20px 20px 0 20px;\">\r\n												<p style=\"color:#FFF !important; font-family:Arial, sans-serif; font-size:12px;\">Copyright &copy; <strong>[newsletters_blogname]</strong> [newsletters_date format=\"%Y\"]</p>\r\n                                            </td>\r\n                                        </tr>\r\n										<tr>\r\n											<td>\r\n												<img src=\"[newsletters_pluginurl]/includes/themes/redray/images/footer-bg.gif\" alt=\"Footer\" height=\"61\" width=\"600\" />\r\n											</td>\r\n										</tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END FOOTER SECTION -->\r\n						</table>\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n			<br />\r\n			<br />\r\n        </center>\r\n    </body>\r\n</html>', 'N', 'N', '#333333', 0, '2023-12-21 10:06:21', '2023-12-21 10:06:21'),
(6, 'Simply Elegant', 'simplyelegant', 'Y', 'paste', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"https://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html lang=\"en\">\r\n	<head>\r\n	   <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n	   <title>[newsletters_subject]</title>\r\n	   <style type=\"text/css\" media=\"screen\">\r\n	      body {\r\n	         background-color: #ffffff;\r\n	         margin: 0;\r\n	         padding: 0;\r\n	      }\r\n	\r\n	      a img {\r\n	         border: none;\r\n	      }\r\n	\r\n	      a {\r\n	         border: none;\r\n	      }\r\n	\r\n	      td.permission {\r\n	         padding: 30px 0 10px 0;\r\n	      }\r\n	\r\n	      .permission {\r\n	         font-family: \'Lucida Grande\';\r\n	         font-size: 10px;\r\n	         color: #666666;\r\n	         padding: 4px 0 4px 0;\r\n	      }\r\n	\r\n	      .permission a {\r\n	         color: #333333;\r\n	      }\r\n	\r\n	      .permission p {\r\n	         margin: 0 0 4px 0;\r\n	      }\r\n	\r\n	      .header {\r\n	         background-color: #353535;\r\n	      }\r\n	\r\n	      .header h1 {\r\n	      	font-family: Georgia;\r\n	      	font-size: 32px;\r\n	      	font-weight: normal;\r\n	      	color: #bfbfbf;\r\n	      	display: inline;\r\n	      	text-align: left;}\r\n	\r\n	      .date h3 {\r\n	      	font-family: Georgia;\r\n	      	font-size: 14px;\r\n	      	color: #bfbfbf;\r\n	      	font-weight: normal;\r\n	      	text-align: right;\r\n	      	display: inline;\r\n	      	font-style: italic;\r\n	      }\r\n	\r\n	      .body {\r\n	         background-color: #ffffff;\r\n	      }\r\n	\r\n	      td.sidebar {\r\n	      	padding: 22px 0 0 0;\r\n	      }\r\n	\r\n	      .sidebar h2 {\r\n	         font-family: Georgia;\r\n	         font-size: 18px;\r\n	         font-weight: bold;\r\n	         color: #808080;\r\n	         margin: 0 0 6px 4px;\r\n	         padding: 0;\r\n	         text-align: left;\r\n	      }\r\n	\r\n	      .sidebar h2.issue {\r\n	         color: #000000;\r\n	         margin: 0 0 10px 10px;\r\n	      }\r\n	\r\n	      .sidebar ul {\r\n	         font-family: Georgia;\r\n	         font-size: 12px;\r\n	         color: #2679b9;\r\n	         margin: 0 0 0 24px;\r\n	         padding: 0;\r\n	         text-align: left;\r\n	      }\r\n	\r\n	      .sidebar ul a {\r\n	      	font-family: Georgia;\r\n	      	font-size: 12px;\r\n	      	color: #2679b9;\r\n	      	font-style: italic;\r\n	      }\r\n	      .sidebar ul li {\r\n	      	margin: 0 0 10px 0;\r\n	      }\r\n	      .sidebar p {\r\n	         font-family: \'Lucida Grande\';\r\n	         font-size: 11px;\r\n	         color: #5f5f5f;\r\n	         padding: 0;\r\n	         margin: 0 0 10px 0;\r\n	         text-align: left;\r\n	      }\r\n	\r\n	      td.sidebg {\r\n	         background-color: #f1f1f1;\r\n	         padding: 10px 16px 10px 16px;\r\n	      }\r\n	\r\n	      td.mainbar {\r\n	      	padding: 20px 10px 20px 10px;\r\n			width: 580px;\r\n			max-width: 580px;\r\n			text-align: left;\r\n	      }\r\n	      \r\n	      .mainbar img {\r\n		      max-width: 100%;\r\n		      height: auto;\r\n	      }\r\n	\r\n	      .mainbar p {\r\n	      	font-family: \'Lucida Grande\';\r\n	      	font-size: 12px;\r\n	      	color: #333333;\r\n	      	margin: 10px 0 20px 0;\r\n	      	text-align: left;\r\n	      }\r\n	\r\n	      .mainbar p.first {\r\n	      	margin-top: 10px;\r\n	      }\r\n	\r\n	      .mainbar h2 {\r\n	      	font-family: \'Lucida Grande\';\r\n	      	font-size: 16px;\r\n	      	color: #000000;\r\n	      	text-transform: uppercase;\r\n	      	margin: 10px 0 16px 0;\r\n	      }\r\n	\r\n	      .mainbar h2 a {\r\n	      	font-family: \'Lucida Grande\';\r\n	      	font-size: 16px;\r\n	      	color: #000000;\r\n	      	text-transform: uppercase;\r\n	      	text-decoration: none;\r\n	      	font-style: normal;\r\n	      }\r\n	\r\n	      .mainbar a {\r\n	      	font-family: Georgia;\r\n	      	font-size: 13px;\r\n	      	color: #2679b9;\r\n	      	font-style: italic;\r\n	      }\r\n	\r\n	      .mainbar a.center {\r\n	      	font-size: 12px;\r\n	      	text-align: center;\r\n	      	display: block;\r\n	      	color: #999999;\r\n	      	padding: 8px 0 12px 0;\r\n	      	text-decoration: none;\r\n	      }\r\n	\r\n	      .mainbar img.inline {\r\n	      	border: 1px solid #dedede;\r\n	      	padding: 4px;\r\n	      }\r\n	\r\n	      td.footer {\r\n	      	padding: 0 0 10px 0;\r\n	      	border-top: 2px solid #ededed;\r\n	      }\r\n	\r\n	      .footer p {\r\n	      	color: #a1a1a1;\r\n	      	font-size: 11px;\r\n	      	margin: 0;\r\n	      	padding: 0;\r\n	      }\r\n	\r\n	      .footer p.first {\r\n	      	margin: 14px 0 0 0;\r\n	      }\r\n	\r\n	      .footer a {\r\n	      	font-family: \'Lucida Grande\';\r\n	      	font-size: 11px;\r\n	      	color: #2679b9;\r\n	      }\r\n	   </style>\r\n	   \r\n   		<style type=\"text/css\" data-premailer=\"ignore\">\r\n		@media screen and (max-width: 660px) {\r\n			#maintable {\r\n				width: 100%; \r\n				max-width: 600px;\r\n			}\r\n			\r\n			#maintable img {\r\n				-ms-interpolation-mode: bicubic; \r\n				max-width: 100%; \r\n				height: auto;\r\n			}\r\n		}\r\n\r\n\r\n		@media screen and (max-width: 768px) {\r\n			img {max-width:  100% !important; height:  auto; }\r\n			.padded {padding-left:  10px; padding-right: 10px;}\r\n			.nav-inner td {\r\n				display: inline-block;\r\n			}\r\n		}\r\n\r\n		@media screen and (max-width: 320px) {\r\n			.inner {padding-left: 0px !important;padding-right: 0px !important;}\r\n\r\n		}\r\n\r\n		@media screen and (max-width: 610px) {\r\n			table.social > tbody > tr > td {\r\n				display: block;\r\n			}\r\n			.content {padding: 15px 0;}\r\n			table {width: 100%;}\r\n		}\r\n\r\n		@media screen and (max-width: 610px) {\r\n			img {\r\n				width: 100% !important;\r\n				object-fit: contain;\r\n			}\r\n\r\n			td {\r\n				width: 100% !important;\r\n			}\r\n\r\n			table#templateFooter {\r\n				width: 100% !important;\r\n			}\r\n		}\r\n\r\n		</style>\r\n	</head>\r\n	<body>\r\n		[newsletters_track]\r\n\r\n		<center>\r\n			<table align=\"center\" bgcolor=\"#ffffff\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n				<tr>\r\n					<td id=\"maintable\" width=\"600\" align=\"center\">\r\n						<!-- header -->\r\n						<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\">\r\n							<tr>\r\n				               <td align=\"center\" class=\"permission\">\r\n				                  <p>You\'re receiving this newsletter because you subscribed to our mailing list.</p>\r\n				                  <p>Not interested anymore? [newsletters_unsubscribe]. <br/>Having trouble viewing this email? [newsletters_online].</p>\r\n				               </td>\r\n				            </tr>\r\n				            <tr>\r\n				               <td height=\"77\" align=\"left\" class=\"header\">\r\n				                  <table border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n				                     <tr>\r\n				                        <td><img src=\"https://newsletters.tribulant.co/wp-content/plugins/wp-mailinglist/includes/themes/simplyelegant/images/header.gif\" alt=\"header\"></td>\r\n				                     </tr>\r\n				                  </table>\r\n				               </td>\r\n				            </tr>\r\n						</table>\r\n						\r\n						<!-- content -->\r\n						<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\">\r\n							<tr>               \r\n				               <td align=\"center\" valign=\"top\" class=\"mainbar\">\r\n				                  <h2>[newsletters_subject]</h2>\r\n				\r\n				                  [newsletters_main_content]\r\n				                  \r\n				                  <p><a href=\"#top\" class=\"center\">Back to top^</a></p>\r\n				                  <p><img src=\"https://newsletters.tribulant.co/wp-content/plugins/wp-mailinglist/includes/themes/simplyelegant/images/hr-large.gif\" alt=\"divider\"></p>\r\n				               </td>\r\n				            </tr>\r\n						</table>\r\n						\r\n						<!-- footer -->\r\n						<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" align=\"center\">\r\n							<tr>\r\n		                        <td class=\"footer\" align=\"center\">\r\n		                           <p class=\"first\">Copyright &copy; <strong>[newsletters_blogname]</strong> [newsletters_date format=\"%Y\"]</p>\r\n		                        </td>\r\n		                     </tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n		</center>\r\n	</body>\r\n</html>', 'N', 'N', '#333333', 0, '2023-12-21 10:06:21', '2023-12-21 10:06:21');
INSERT INTO `wp_wpmlthemes` (`id`, `title`, `name`, `premade`, `type`, `content`, `def`, `defsystem`, `acolor`, `themestylesheet`, `created`, `modified`) VALUES
(7, 'Snazzy', 'snazzy', 'Y', 'paste', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"https://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html>\r\n<head>\r\n   <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">\r\n   <title>[newsletters_subject]</title>\r\n   <style type=\"text/css\" media=\"screen\">\r\n			#outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" button. */\r\n			body{width:100% !important;} .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\r\n			body{-webkit-text-size-adjust:none;} /* Prevent Webkit platforms from changing default text sizes. */\r\n\r\n			body {margin:0; padding:0;}\r\n			img {border:0; outline:none; text-decoration:none;}\r\n			table td {border-collapse:collapse;}\r\n			\r\n			h1, .h1{\r\n				color:#333333 !important;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:24px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n\r\n			h2, .h2{\r\n				color:#333333 !important;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:18px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n\r\n			h3, .h3{\r\n				color:#333333 !important;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:16px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n\r\n			h4, .h4{\r\n				color:#333333 !important;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n			\r\n			h5, .h5{\r\n				color:#333333 !important;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n			\r\n			div{\r\n				color:#666666 !important;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			@media screen and (max-width: 768px) {\r\n				img {max-width:  100% !important; height:  auto; }\r\n				.padded {padding-left:  10px; padding-right: 10px;}\r\n				.nav-inner td {\r\n					display: inline-block;\r\n				}\r\n			}\r\n\r\n			@media screen and (max-width: 320px) {\r\n				.inner {padding-left: 0px !important;padding-right: 0px !important;}\r\n\r\n			}\r\n\r\n			@media screen and (max-width: 610px) {\r\n				table.social > tbody > tr > td {\r\n					display: block;\r\n				}\r\n				.content {padding: 15px 0;}\r\n				table {width: 100%;}\r\n			}\r\n\r\n			@media screen and (max-width: 610px) {\r\n				img {\r\n					width: 100% !important;\r\n					object-fit: contain;\r\n				}\r\n\r\n				td {\r\n					width: 100% !important;\r\n				}\r\n\r\n				table#templateFooter {\r\n					width: 100% !important;\r\n				}\r\n			}\r\n\r\n   </style>\r\n\r\n</head>\r\n    <body style=\"background-color:#FFFFFF;\" leftmargin=\"0\" marginwidth=\"0\" topmargin=\"0\" marginheight=\"0\" offset=\"0\">\r\n    	[newsletters_track]\r\n    	<center>\r\n        	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" height=\"100%\" width=\"100%\" style=\"background:#FFFFFF;\" id=\"backgroundTable\">\r\n            	<tr>\r\n                	<td align=\"center\" valign=\"top\">\r\n					\r\n						<!-- BEGIN TOP SECTION -->\r\n                        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"580\" style=\"background:#FFFFFF;\">\r\n                            <tr>\r\n                                <td valign=\"top\">\r\n                                    <table border=\"0\" cellpadding=\"15\" cellspacing=\"0\" width=\"580\">\r\n                                    	<tr>\r\n                                        	<td valign=\"top\">\r\n                                            	<div style=\"color:#000 !important; font-size:11px; line-height:16px; font-family:Arial, sans-serif;\">\r\n													<center>\r\n														<p>\r\n															You\'re receiving this newsletter because you subscribed to our mailing list.<br />\r\n															Not interested anymore? [newsletters_unsubscribe]. <br/>\r\n															Having trouble viewing this email? [newsletters_online].\r\n														</p>\r\n													</center>\r\n                                                </div>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n                        </table>\r\n						<!-- END TOP SECTION -->\r\n						\r\n						<!-- BEGIN CONTENT SECTION -->\r\n                    	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"580\" style=\"background:#FFFFFF;\">\r\n						\r\n							<!-- BEGIN HEADER SECTION -->\r\n                        	<tr>\r\n                            	<td style=\"background-color:#FFFFFF;\" align=\"center\" valign=\"bottom\">\r\n									<img src=\"[newsletters_pluginurl]/includes/themes/snazzy/images/header.jpg\" width=\"580\" height=\"119\" />\r\n                                </td>\r\n                            </tr>\r\n							<!-- END HEADER SECTION -->\r\n							\r\n							<!-- BEGIN TEXT SECTION -->\r\n                        	<tr>\r\n                            	<td valign=\"top\" align=\"center\">\r\n                                    <table border=\"0\" cellspacing=\"0\" cellpadding=\"20\" width=\"580\">\r\n                                    	<tr>\r\n                                        	<td valign=\"top\">\r\n                                            	<div style=\"border-top:8px solid #ED5D9A; border-bottom:8px solid #ED5D9A; color:#333; font-size:14px; line-height:21px; font-family:Helvetica, Arial, sans-serif;\">												   \r\n												   <br />\r\n												   <h2 style=\"color:#ED5D9A !important;\">[newsletters_subject]</h2>\r\n												   [newsletters_main_content]\r\n												   <br />\r\n												   <br />\r\n												</div>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END TEXT SECTION -->\r\n							<!-- BEGIN FOOTER SECTION -->\r\n                        	<tr>\r\n								<td valign=\"middle\" align=\"middle\">\r\n									<p style=\"color:#999 !important; font-family:Arial, sans-serif; font-size:12px;\">Copyright &copy; <strong>[newsletters_blogname]</strong> [newsletters_date format=\"%Y\"]</p>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END FOOTER SECTION -->\r\n						</table>\r\n						<!-- END CONTENT SECTION -->\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n			<br />\r\n			<br />\r\n        </center>\r\n    </body>\r\n</html>', 'N', 'N', '#333333', 0, '2023-12-21 10:06:21', '2023-12-21 10:06:21'),
(8, 'Pro News', 'pronews', 'Y', 'paste', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"https://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html>\r\n    <head>\r\n        <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />        \r\n        <title>[newsletters_subject]</title>\r\n		<style type=\"text/css\">\r\n			#outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" button. */\r\n			body{width:100% !important;} .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\r\n			body{-webkit-text-size-adjust:none;} /* Prevent Webkit platforms from changing default text sizes. */\r\n\r\n			body{margin:0; padding:0;}\r\n			img{border:0; height:auto; line-height:100%; outline:none; text-decoration:none;}\r\n			table td{border-collapse:collapse;}\r\n			#backgroundTable{height:100% !important; margin:0; padding:0; width:100% !important;}\r\n\r\n			body, #backgroundTable{\r\n				background-color:#636363;\r\n			}\r\n\r\n			#templateContainer{\r\n				border: 6px solid #454545;\r\n			}\r\n\r\n			h1, .h1{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:34px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n\r\n			h2, .h2{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:30px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n\r\n			h3, .h3{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:26px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n\r\n			h4, .h4{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:18px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n			\r\n			h5, .h5{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n			\r\n			#templatePreheader{\r\n				background-color:#636363;\r\n			}\r\n			\r\n			.preheaderContent div{\r\n				color:#FFF;\r\n				font-family:Arial;\r\n				font-size:11px;\r\n				line-height:100%;\r\n				text-align:left;\r\n			}\r\n\r\n			.preheaderContent div a:link, .preheaderContent div a:visited, .preheaderContent div a .yshortcuts{\r\n				color:#CCC;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			#templateHeader{\r\n				background-color:#FFFFFF;\r\n				border-bottom:0;\r\n			}\r\n\r\n			.headerContent{\r\n				color:#4d4d4d;\r\n				font-family:Arial;\r\n				font-size:34px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				padding:0;\r\n				text-align:center;\r\n				vertical-align:middle;\r\n			}\r\n\r\n			.headerContent a:link, .headerContent a:visited, .headerContent a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			#headerImage{\r\n				height:auto;\r\n				max-width:600px !important;\r\n			}\r\n\r\n			#templateContainer, .bodyContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.bodyContent div{\r\n				color:#505050;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.bodyContent div a:link, .bodyContent div a:visited, .bodyContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.bodyContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n			\r\n			#headerBody a:link, #headerBody a:visited, #headerBody a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n				font-size:14px;\r\n				font-family:Helvetica, Arial, sans-serif;\r\n			}\r\n\r\n			.leftMidColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.leftMidColumnContent div{\r\n				color:#505050;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.leftMidColumnContent div a:link, .leftMidColumnContent div a:visited, .leftMidColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.leftMidColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n\r\n			.rightMidColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.rightMidColumnContent div{\r\n				color:#505050;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.rightMidColumnContent div a:link, .rightMidColumnContent div a:visited, .rightMidColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.rightMidColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n\r\n			.leftLowerColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.leftLowerColumnContent div{\r\n				color:#505050;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.leftLowerColumnContent div a:link, .leftLowerColumnContent div a:visited, .leftLowerColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.leftLowerColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n\r\n			.centerLowerColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.centerLowerColumnContent div{\r\n				color:#505050;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n			\r\n			.centerLowerColumnContent div a:link, .centerLowerColumnContent div a:visited, .centerLowerColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.centerLowerColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n\r\n			.rightLowerColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.rightLowerColumnContent div{\r\n				color:#505050;\r\n				font-family:Arial;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.rightLowerColumnContent div a:link, .rightLowerColumnContent div a:visited, .rightLowerColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.rightLowerColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n			\r\n			#templateFooterSocial a, #templateFooterSocial a:visited, #templateFooterSocial a .yshortcuts {\r\n				color: #336699;\r\n				font-family: Helvetica,Arial,sans-serif;\r\n				font-size: 14px;\r\n				font-weight: normal;\r\n				text-decoration: underline;\r\n			}\r\n			\r\n			#templateFooter{\r\n				background-color:#eeeeee;\r\n				border-top:1px solid #dddddd;\r\n				line-height:155%;\r\n			}\r\n\r\n			.footerContent div{\r\n				color:#707070;\r\n				font-family:Arial;\r\n				font-size:12px;\r\n				line-height:185%;\r\n				text-align:left;\r\n			}\r\n\r\n			.footerContent div a:link, .footerContent div a:visited, .footerContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.footerContent img{\r\n				display:inline;\r\n			}\r\n\r\n			#social{\r\n				background-color:#FAFAFA;\r\n				border:0;\r\n			}\r\n\r\n			#social div{\r\n				text-align:center;\r\n			}\r\n\r\n			#utility{\r\n				background-color:#FFFFFF;\r\n				border:0;\r\n			}\r\n\r\n			#utility div{\r\n				text-align:center;\r\n			}\r\n\r\n\r\n			@media screen and (max-width: 768px) {\r\n				img {max-width:  100% !important; height:  auto; }\r\n				.padded {padding-left:  10px; padding-right: 10px;}\r\n				.nav-inner td {\r\n					display: inline-block;\r\n				}\r\n			}\r\n\r\n			@media screen and (max-width: 320px) {\r\n				.inner {padding-left: 0px !important;padding-right: 0px !important;}\r\n\r\n			}\r\n\r\n			@media screen and (max-width: 610px) {\r\n				table.social > tbody > tr > td {\r\n					display: block;\r\n				}\r\n				.content {padding: 15px 0;}\r\n				table {width: 100%;}\r\n			}\r\n\r\n			@media screen and (max-width: 610px) {\r\n				img {\r\n					width: 100% !important;\r\n					object-fit: contain;\r\n				}\r\n\r\n				td {\r\n					width: 100% !important;\r\n				}\r\n\r\n				table#templateFooter {\r\n					width: 100% !important;\r\n				}\r\n			}\r\n\r\n		</style>\r\n	</head>\r\n    <body leftmargin=\"0\" marginwidth=\"0\" topmargin=\"0\" marginheight=\"0\" offset=\"0\">\r\n    	[newsletters_track]\r\n    \r\n    	<center>\r\n        	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" height=\"100%\" width=\"100%\" style=\"background:#636363;\" id=\"backgroundTable\">\r\n            	<tr>\r\n                	<td align=\"center\" valign=\"top\">\r\n					\r\n						<!-- BEGIN TOP SECTION -->\r\n                        <table border=\"0\" cellpadding=\"10\" cellspacing=\"0\" width=\"600\" id=\"templatePreheader\">\r\n                            <tr>\r\n                                <td valign=\"top\" class=\"preheaderContent\">\r\n                                \r\n                                    <table border=\"0\" cellpadding=\"10\" cellspacing=\"0\" width=\"100%\">\r\n                                    	<tr>\r\n                                        	<td valign=\"top\">\r\n                                            	<div style=\"color:#FFF; font-size:12px; font-family:Helvetica, Arial, sans-serif;\">\r\n                                                	<center>Trouble viewing this email? <span style=\"color:#999;\">[newsletters_online]</span></center>\r\n                                                </div>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n									\r\n                                </td>\r\n                            </tr>\r\n                        </table>\r\n						<!-- END TOP SECTION -->\r\n						\r\n						<!-- BEGIN CONTENT SECTION -->\r\n                    	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" style=\"background:#FFF; border:6px solid #454545;\" id=\"templateContainer\">\r\n							<!-- BEGIN HEADER SECTION -->\r\n                        	<tr>\r\n                            	<td align=\"center\" valign=\"top\">\r\n                                	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" id=\"headerBody\">\r\n                                    	<tr>\r\n                                        	<td valign=\"top\">\r\n                                            	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\">\r\n                                                	<tr>\r\n                                                    	<td valign=\"top\" class=\"bodyContent\">\r\n                                                            <table border=\"0\" cellpadding=\"20\" cellspacing=\"0\" width=\"100%\">\r\n                                                                <tr>\r\n                                                                    <td width=\"270\" valign=\"top\">\r\n																		<img src=\"[newsletters_pluginurl]/includes/themes/pronews/images/logo.png\" width=\"270\" height=\"40\" />\r\n                                                                    </td>\r\n																	<td width=\"20\">&nbsp;</td>\r\n																	<td width=\"270\" valign=\"middle\" align=\"right\">\r\n																		<span style=\"font-size:12px; font-family:Helvetica, Arial, sans-serif;\">[newsletters_date]</span>\r\n                                                                    </td>\r\n                                                                </tr>\r\n                                                            </table>\r\n                                                        </td>\r\n                                                    </tr>\r\n                                                </table>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END HEADER SECTION -->\r\n							<!-- BEGIN BANNER SECTION -->\r\n                        	<tr>\r\n                            	<td align=\"center\" valign=\"top\">\r\n                                	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" id=\"templateHeader\">\r\n                                        <tr>\r\n                                            <td class=\"headerContent\">\r\n                                            	<img src=\"[newsletters_pluginurl]/includes/themes/pronews/images/banner.jpg\" style=\"max-width:600px;\" id=\"headerImage campaign-icon\" />\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END BANNER SECTION -->\r\n							<!-- BEGIN TEXT SECTION -->\r\n                        	<tr>\r\n                            	<td align=\"center\" valign=\"top\">\r\n                                	<table border=\"0\" cellpadd