eader\">\r\n                            <tr>\r\n                                <td valign=\"top\" class=\"preheaderContent\">\r\n                                \r\n                                    <table border=\"0\" cellpadding=\"10\" cellspacing=\"0\" width=\"100%\">\r\n                                    	<tr>\r\n                                        	<td valign=\"top\">\r\n                                            	<div style=\"color:#666; font-size:12px; font-family:Helvetica, Arial, sans-serif;\">\r\n                                                	<center>Trouble viewing this email? [newsletters_online]</center>\r\n                                                </div>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n									\r\n                                </td>\r\n                            </tr>\r\n                        </table>\r\n						<!-- END TOP SECTION -->\r\n						\r\n						<!-- BEGIN CONTENT SECTION -->\r\n                    	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" style=\"background:#ededed; border:0;\" id=\"templateContainer\">\r\n							<!-- BEGIN HEADER SECTION -->\r\n                        	<tr>\r\n                            	<td align=\"center\" valign=\"top\">\r\n                                	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" id=\"headerBody\">\r\n										<tr>\r\n											<td valign=\"bottom\">\r\n												<img style=\"display:block;margin:0;padding:0;\" src=\"[newsletters_pluginurl]/includes/themes/lagoon/images/blue-rounded-top.png\" width=\"600\" height=\"10\" />\r\n											</td>\r\n										</tr>\r\n                                    	<tr>\r\n                                        	<td valign=\"top\">\r\n                                            	<table border=\"0\" cellpadding=\"0\" style=\"background:#3695f7;\" cellspacing=\"0\" width=\"600\">\r\n                                                	<tr>\r\n                                                    	<td valign=\"top\">\r\n                                                            <table border=\"0\" cellpadding=\"20\" cellspacing=\"0\" width=\"100%\">\r\n                                                                <tr>\r\n                                                                    <td width=\"166\" valign=\"middle\">\r\n																		<img src=\"[newsletters_pluginurl]/includes/themes/lagoon/images/logo.png\" width=\"166\" height=\"60\" />\r\n                                                                    </td>\r\n																	<td width=\"20\">&nbsp;</td>\r\n																	<td width=\"270\" valign=\"middle\" align=\"right\" style=\"color:#FFF; font-family:Helvetica, Arial, sans-serif;\">\r\n																		Issue #[newsletters_historyid]<br />\r\n																		[newsletters_date]\r\n                                                                    </td>\r\n                                                                </tr>\r\n                                                            </table>\r\n                                                        </td>\r\n                                                    </tr>\r\n                                                </table>\r\n                                            </td>\r\n                                        </tr>\r\n										<tr>\r\n											<td valign=\"bottom\">\r\n												<img style=\"display:block;margin:0;padding:0;\" src=\"[newsletters_pluginurl]/includes/themes/lagoon/images/blue-rounded-bottom.png\" width=\"600\" height=\"10\" />\r\n											</td>\r\n										</tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END HEADER SECTION -->\r\n							\r\n							<!-- BEGIN SEPARATOR -->\r\n							<tr>\r\n								<td valign=\"top\" height=\"20\">\r\n									&nbsp;\r\n								</td>\r\n							</tr>\r\n							<!-- END SEPARATOR -->\r\n							\r\n							<!-- BEGIN BANNER SECTION -->\r\n                        	<tr>\r\n                            	<td align=\"center\" valign=\"top\">\r\n                                	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" id=\"templateHeader\">\r\n                                        <tr>\r\n                                            <td valign=\"bottom\" class=\"headerContent\">\r\n                                            	<img src=\"[newsletters_pluginurl]/includes/themes/lagoon/images/banner.jpg\" style=\"display:block;margin:0;padding:0;max-width:600px;\" id=\"headerImage campaign-icon\" />\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END BANNER SECTION -->\r\n							\r\n							<!-- BEGIN SEPARATOR -->\r\n							<tr>\r\n								<td valign=\"top\" height=\"20\">\r\n									&nbsp;\r\n								</td>\r\n							</tr>\r\n							<!-- END SEPARATOR -->\r\n							\r\n							<!-- BEGIN TEXT SECTION -->\r\n                        	<tr>\r\n                            	<td align=\"center\" valign=\"top\">\r\n                                	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\" id=\"templateBody\">\r\n                                    	<tr>\r\n                                        	<td valign=\"top\">\r\n                                            	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\">\r\n													<tr>\r\n														<td valign=\"bottom\">\r\n															<img style=\"display:block;margin:0;padding:0;\" src=\"[newsletters_pluginurl]/includes/themes/lagoon/images/white-rounded-top.png\" height=\"10\" width=\"600\" />\r\n														</td>\r\n													</tr>\r\n                                                	<tr>\r\n                                                    	<td valign=\"top\" class=\"bodyContent\">\r\n                                                            <table border=\"0\" cellpadding=\"20\" cellspacing=\"0\" width=\"100%\">\r\n\r\n                                                                <tr>\r\n                                                                    <td valign=\"top\" style=\"background:#FFF\">\r\n 			                                                            <div style=\"color: #505050; font-family: Arial; font-size: 14px; line-height: 150%; text-align: left;\">\r\n			                                                                <h4 style=\"color: #4D4D4D; display: block; font-family: Arial; font-size: 18px; font-weight: bold; line-height: 100%; margin: 0 0 10px; text-align: left;\" class=\"h4\">[newsletters_subject]</h4>\r\n			                                                                [newsletters_main_content]\r\n																		</div>\r\n                                                                    </td>\r\n                                                                </tr>\r\n                                                            </table>\r\n                                                        </td>\r\n                                                    </tr>\r\n													<tr>\r\n														<td valign=\"bottom\">\r\n															<img style=\"display:block;margin:0;padding:0;\" src=\"[newsletters_pluginurl]/includes/themes/lagoon/images/white-rounded-bottom.png\" height=\"10\" width=\"600\" />\r\n														</td>\r\n													</tr>\r\n                                                </table>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END TEXT SECTION -->\r\n							<!-- BEGIN SEPARATOR -->\r\n							<tr>\r\n								<td valign=\"top\" height=\"20\">\r\n									&nbsp;\r\n								</td>\r\n							</tr>\r\n							<!-- END SEPARATOR -->\r\n							<!-- BEGIN FOOTER SECTION -->\r\n                        	<tr>\r\n                            	<td align=\"center\" valign=\"top\">\r\n                                	<table border=\"0\" cellspacing=\"0\" width=\"600\" style=\"background:#ededed; border:0;\" id=\"templateFooter\">\r\n										<tr>\r\n											<td valign=\"top\" class=\"footerContent\">\r\n													\r\n												<table border=\"0\" cellspacing=\"0\" width=\"100%\">\r\n													<tr>\r\n														<td valign=\"top\">\r\n															<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"600\">\r\n																<tr>\r\n																	<td valign=\"bottom\">\r\n																		<img style=\"display:block;margin:0;padding:0;\" src=\"[newsletters_pluginurl]/includes/themes/lagoon/images/blue-rounded-top.png\" width=\"600\" height=\"10\" />\r\n																	</td>\r\n																</tr>\r\n																<tr>\r\n																	<td valign=\"top\" style=\"background:#3695f7;\">\r\n																		<table border=\"0\" cellpadding=\"20\" cellspacing=\"0\" width=\"100%\">\r\n																			<tr>\r\n																				<td width=\"600\" valign=\"middle\" align=\"center\" style=\"color:#FFF; font-family:Helvetica, Arial, sans-serif; font-size:14px; line-height:140%;\">\r\n																					[newsletters_lagoon_address]<br />\r\n																					<a href=\"[newsletters_siteurl]\">[newsletters_blogname]</a> | <a href=\"mailto:<?php echo get_bloginfo(\'admin_email\'); ?>\"><?php echo get_bloginfo(\'admin_email\'); ?></a><br />\r\n																					Sales and Support: +1 (555) 555-5555 \r\n																				</td>\r\n																			</tr>\r\n																		</table>\r\n																	</td>\r\n																</tr>\r\n																<tr>\r\n																	<td valign=\"bottom\">\r\n																		<img style=\"display:block;margin:0;padding:0;\" src=\"[newsletters_pluginurl]/includes/themes/lagoon/images/blue-rounded-bottom.png\" width=\"600\" height=\"10\" />\r\n																	</td>\r\n																</tr>\r\n															</table>\r\n														</td>\r\n													</tr>\r\n												</table>\r\n                                            \r\n                                            </td>\r\n                                        </tr>\r\n                                    </table>\r\n                                </td>\r\n                            </tr>\r\n							<!-- END FOOTER SECTION -->\r\n                        </table>\r\n						<!-- END CONTENT SECTION -->\r\n						\r\n                        <br />\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </center>\r\n    </body>\r\n</html>', 'N', 'N', '#333333', 0, '2023-12-21 10:06:21', '2023-12-21 10:06:21');
INSERT INTO `wp_wpmlthemes` (`id`, `title`, `name`, `premade`, `type`, `content`, `def`, `defsystem`, `acolor`, `themestylesheet`, `created`, `modified`) VALUES
(10, 'The Mailer', 'themailer', 'Y', 'paste', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"https://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html>\r\n    <head>\r\n        <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />        \r\n        <title>[newsletters_subject]</title>\r\n		<style type=\"text/css\">\r\n			#outlook a{padding:0;} /* Force Outlook to provide a \"view in browser\" button. */\r\n			body{width:100% !important;} .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */\r\n			body{-webkit-text-size-adjust:none;} /* Prevent Webkit platforms from changing default text sizes. */\r\n\r\n			body{margin:0; padding:0;}\r\n			img{border:0; height:auto; line-height:100%; outline:none; text-decoration:none;}\r\n			table td{border-collapse:collapse;}\r\n			#backgroundTable{height:100% !important; margin:0; padding:0; width:100% !important;}\r\n\r\n			body, #backgroundTable{\r\n				background-color:#FFF;\r\n			}\r\n\r\n			#templateContainer{\r\n				border: 6px solid #454545;\r\n			}\r\n\r\n			h1, .h1{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Georgia;\r\n				font-size:34px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n\r\n			h2, .h2{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Georgia;\r\n				font-size:30px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n\r\n			h3, .h3{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Georgia;\r\n				font-size:26px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n\r\n			h4, .h4{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Georgia;\r\n				font-size:18px;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n			\r\n			h5, .h5{\r\n				color:#4d4d4d;\r\n				display:block;\r\n				font-family:Georgia;\r\n				font-size:14px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				margin-top:0;\r\n				margin-right:0;\r\n				margin-bottom:10px;\r\n				margin-left:0;\r\n				text-align:left;\r\n			}\r\n			\r\n			#templatePreheader{\r\n				background-color:#FFF;\r\n			}\r\n			\r\n			.preheaderContent div{\r\n				color:#FFF;\r\n				font-family:Georgia;\r\n				font-size:11px;\r\n				line-height:100%;\r\n				text-align:left;\r\n			}\r\n\r\n			.preheaderContent div a:link, .preheaderContent div a:visited, .preheaderContent div a .yshortcuts{\r\n				color:#999;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			#templateHeader{\r\n				background-color:#FFFFFF;\r\n				border-bottom:0;\r\n			}\r\n\r\n			.headerContent{\r\n				color:#4d4d4d;\r\n				font-family:Georgia;\r\n				font-size:34px;\r\n				font-weight:bold;\r\n				line-height:100%;\r\n				padding:0;\r\n				text-align:center;\r\n				vertical-align:middle;\r\n			}\r\n\r\n			.headerContent a:link, .headerContent a:visited, .headerContent a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			#headerImage{\r\n				height:auto;\r\n				max-width:600px !important;\r\n			}\r\n\r\n			#templateContainer, .bodyContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.bodyContent div{\r\n				color:#505050;\r\n				font-family:Georgia;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.bodyContent div a:link, .bodyContent div a:visited, .bodyContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.bodyContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n			\r\n			#headerBody a:link, #headerBody a:visited, #headerBody a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n				font-size:14px;\r\n				font-family:Helvetica, Georgia, sans-serif;\r\n			}\r\n\r\n			.leftMidColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.leftMidColumnContent div{\r\n				color:#505050;\r\n				font-family:Georgia;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.leftMidColumnContent div a:link, .leftMidColumnContent div a:visited, .leftMidColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.leftMidColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n\r\n			.rightMidColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.rightMidColumnContent div{\r\n				color:#505050;\r\n				font-family:Georgia;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.rightMidColumnContent div a:link, .rightMidColumnContent div a:visited, .rightMidColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.rightMidColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n\r\n			.leftLowerColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.leftLowerColumnContent div{\r\n				color:#505050;\r\n				font-family:Georgia;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.leftLowerColumnContent div a:link, .leftLowerColumnContent div a:visited, .leftLowerColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.leftLowerColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n\r\n			.centerLowerColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.centerLowerColumnContent div{\r\n				color:#505050;\r\n				font-family:Georgia;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n			\r\n			.centerLowerColumnContent div a:link, .centerLowerColumnContent div a:visited, .centerLowerColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.centerLowerColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n\r\n			.rightLowerColumnContent{\r\n				background-color:#FFFFFF;\r\n			}\r\n\r\n			.rightLowerColumnContent div{\r\n				color:#505050;\r\n				font-family:Georgia;\r\n				font-size:14px;\r\n				line-height:150%;\r\n				text-align:left;\r\n			}\r\n\r\n			.rightLowerColumnContent div a:link, .rightLowerColumnContent div a:visited, .rightLowerColumnContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.rightLowerColumnContent img{\r\n				display:inline;\r\n				height:auto;\r\n			}\r\n			\r\n			#templateFooterSocial a, #templateFooterSocial a:visited, #templateFooterSocial a .yshortcuts {\r\n				color: #336699;\r\n				font-family: Helvetica,Georgia,sans-serif;\r\n				font-size: 14px;\r\n				font-weight: normal;\r\n				text-decoration: underline;\r\n			}\r\n			\r\n			#templateFooter{\r\n				line-height:155%;\r\n				font-family:Helvetica, Arial, sans-serif;\r\n			}\r\n\r\n			.footerContent div{\r\n				color:#707070;\r\n				font-family:Georgia;\r\n				font-size:12px;\r\n				line-height:185%;\r\n				text-align:left;\r\n			}\r\n\r\n			.footerContent div a:link, .footerContent div a:visited, .footerContent div a .yshortcuts {\r\n				color:#336699;\r\n				font-weight:normal;\r\n				text-decoration:underline;\r\n			}\r\n\r\n			.footerContent img{\r\n				display:inline;\r\n			}\r\n\r\n			#social{\r\n				background-color:#FAFAFA;\r\n				border:0;\r\n			}\r\n\r\n			#social div{\r\n				text-align:center;\r\n			}\r\n\r\n			#utility{\r\n				background-color:#FFFFFF;\r\n				border:0;\r\n			}\r\n\r\n			#utility div{\r\n				text-align:center;\r\n			}\r\n\r\n			@media screen and (max-width: 768px) {\r\n				img {max-width:  100% !important; height:  auto; }\r\n				.padded {padding-left:  10px; padding-right: 10px;}\r\n				.nav-inner td {\r\n					display: inline-block;\r\n				}\r\n			}\r\n\r\n			@media screen and (max-width: 320px) {\r\n				.inner {padding-left: 0px !important;padding-right: 0px !important;}\r\n\r\n			}\r\n\r\n			@media screen and (max-width: 610px) {\r\n				table.social > tbody > tr > td {\r\n					display: block;\r\n				}\r\n				.content {padding: 15px 0;}\r\n				table {width: 100%;}\r\n			}\r\n\r\n			@media screen and (max-width: 610px) {\r\n				img {\r\n					width: 100% !important;\r\n					object-fit: contain;\r\n				}\r\n\r\n				td {\r\n					width: 100% !important;\r\n				}\r\n\r\n				table#templateFooter {\r\n					width: 100% !important;\r\n				}\r\n			}\r\n\r\n		</style>\r\n	</head>\r\n    <body leftmargin=\"0\" marginwidth=\"0\" topmargin=\"0\" marginheight=\"0\" offset=\"0\">\r\n    	[newsletters_track]\r\n    \r\n    	<center>\r\n        	<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" height=\"100%\" width=\"100%\" style=\"background:#FFF;\" id=\"backgroundTable\">\r\n				<tr>\r\n					<td align=\"center\" valign=\"top\">\r\n						<!-- BEGIN TOP SECTION -->\r\n						<table border=\"0\" cellpadding=\"10\" cellspacing=\"0\" width=\"560\" id=\"templatePreheader\">\r\n							<tr>\r\n								<td valign=\"top\" class=\"preheaderContent\">\r\n								\r\n									<table border=\"0\" cellpadding=\"10\" cellspacing=\"0\" width=\"100%\">\r\n										<tr>\r\n											<td valign=\"top\">\r\n												<div style=\"color:#666; font-size:12px; font-family:Helvetica, Georgia, sans-serif;\">\r\n													<center>Trouble viewing this email? <span style=\"color:#999;\">[newsletters_online]</span></center>\r\n												</div>\r\n											</td>\r\n										</tr>\r\n									</table>\r\n									\r\n								</td>\r\n							</tr>\r\n						</table>\r\n						<!-- END TOP SECTION -->\r\n					</td>\r\n				</tr>\r\n            	<tr>\r\n                	<td align=\"center\" valign=\"top\">\r\n					\r\n						<table border=\"0\" cellpadding=\"20\" cellspacing=\"0\" width=\"560\" style=\"background:url([newsletters_pluginurl]/includes/themes/themailer/images/bg.png);\">\r\n							<tr>\r\n								<td>									\r\n									<!-- BEGIN CONTENT SECTION -->\r\n									<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"560\" style=\"background:#FFF; border:0;\" id=\"templateContainer\">\r\n										<!-- BEGIN HEADER SECTION -->\r\n										<tr>\r\n											<td align=\"center\" valign=\"top\">\r\n												<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"560\" id=\"headerBody\">\r\n													<tr>\r\n														<td valign=\"top\">\r\n															<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"560\">\r\n																<tr>\r\n																	<td valign=\"top\" class=\"bodyContent\">\r\n																		<table border=\"0\" cellpadding=\"20\" cellspacing=\"0\" width=\"100%\">\r\n																			<tr>\r\n																				<td width=\"560\" valign=\"top\">\r\n																					<img src=\"[newsletters_pluginurl]/includes/themes/themailer/images/logo.png\" width=\"560\" height=\"110\" />\r\n																				</td>\r\n																			</tr>\r\n																		</table>\r\n																	</td>\r\n																</tr>\r\n															</table>\r\n														</td>\r\n													</tr>\r\n												</table>\r\n											</td>\r\n										</tr>\r\n										<!-- END HEADER SECTION -->\r\n										<!-- BEGIN BANNER SECTION -->\r\n										<tr>\r\n											<td align=\"center\" valign=\"top\">\r\n												<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"560\" id=\"templateHeader\">\r\n													<tr>\r\n														<td align=\"center\" class=\"headerContent\">\r\n															<img src=\"[newsletters_pluginurl]/includes/themes/themailer/images/banner.jpg\" style=\"max-width:600px;\" id=\"headerImage campaign-icon\" />\r\n														</td>\r\n													</tr>\r\n												</table>\r\n											</td>\r\n										</tr>\r\n										<!-- END BANNER SECTION -->\r\n										<!-- BEGIN TEXT SECTION -->\r\n										<tr>\r\n											<td align=\"center\" valign=\"top\">\r\n												<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"520\" id=\"templateBody\">\r\n													<tr>\r\n														<td valign=\"top\">\r\n															<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"560\">\r\n																<tr>\r\n																	<td valign=\"top\" class=\"bodyContent\">\r\n																		<table border=\"0\" cellpadding=\"20\" cellspacing=\"0\" width=\"100%\">\r\n																			<tr>\r\n																				<td valign=\"top\">\r\n																					<div style=\"color: #505050; font-family: Arial; font-size: 14px; line-height: 150%; text-align: left;\">\r\n																						<h4 style=\"color: #4D4D4D; display: block; font-family: Georgia; font-size: 18px; line-height: 100%; margin: 0 0 10px; text-align: left;\" class=\"h4\">[newsletters_subject]</h4>\r\n																						[newsletters_main_content]\r\n																					</div>\r\n																				</td>\r\n																			</tr>\r\n																		</table>\r\n																	</td>\r\n																</tr>\r\n															</table>\r\n														</td>\r\n													</tr>\r\n												</table>\r\n											</td>\r\n										</tr>\r\n										<!-- END TEXT SECTION -->\r\n										<!-- BEGIN FOOTER SECTION -->\r\n										<tr>\r\n											<td align=\"center\" valign=\"top\">\r\n												<table border=\"0\" cellpadding=\"10\" cellspacing=\"0\" width=\"560\" id=\"templateFooter\">\r\n													<tr>\r\n														<td valign=\"top\" class=\"footerContent\">\r\n														\r\n															<table border=\"0\" cellpadding=\"10\" cellspacing=\"0\" width=\"100%\">\r\n																<tr>\r\n																	<td width=\"310\" valign=\"top\">\r\n																		<div style=\"color: #666; font-family: Arial; font-size: 12px; line-height: 185%;\">\r\n																			<h5 style=\"font-size:14px; font-family:Georgia; line-height:100%; margin:0 0 10px; color:#4d4d4d;\">Contact Us</h5>\r\n																			<p>\r\n																				123 My Street<br/>\r\n																				My City<br/>\r\n																				My State<br/>\r\n																				My Country<br/>\r\n																				12345\r\n																			</p>\r\n																		</div>\r\n																	</td>\r\n																	<td width=\"110\">&nbsp;</td>\r\n																	<td width=\"200\" valign=\"middle\">\r\n																		<table align=\"right\" cellpadding=\"0\" cellspacing=\"0\" width=\"200\" id=\"templateFooterSocial\">\r\n																			<tr>\r\n																				<td width=\"16\">\r\n																					<img src=\"[newsletters_pluginurl]/includes/themes/pronews/images/facebook-icon.png\" width=\"16\" height=\"16\" />\r\n																				</td>\r\n																				<td width=\"8\">&nbsp;</td>\r\n																				<td width=\"176\">\r\n																					<a href=\"#\">Be a fan on Facebook</a>\r\n																				</td>\r\n																			</tr>\r\n																			\r\n																			<tr>\r\n																				<td width=\"16\">\r\n																					<img src=\"[newsletters_pluginurl]/includes/themes/pronews/images/twitter-icon.png\" width=\"16\" height=\"16\" />\r\n																				</td>\r\n																				<td width=\"8\">&nbsp;</td>\r\n																				<td width=\"176\">\r\n																					<a href=\"#\">Follow us on Twitter</a>\r\n																				</td>\r\n																			</tr>\r\n																			\r\n																			<tr>\r\n																				<td width=\"16\">\r\n																					<img src=\"[newsletters_pluginurl]/includes/themes/pronews/images/feeds-icon.png\" width=\"16\" height=\"16\" />\r\n																				</td>\r\n																				<td width=\"8\">&nbsp;</td>\r\n																				<td width=\"176\">\r\n																					<a href=\"#\">RSS Feed</a>\r\n																				</td>\r\n																			</tr>\r\n																		</table>\r\n																	</td>\r\n																</tr>\r\n															</table>\r\n														\r\n														</td>\r\n													</tr>\r\n												</table>\r\n											</td>\r\n										</tr>\r\n										<!-- END FOOTER SECTION -->\r\n									</table>\r\n									<!-- END CONTENT SECTION -->\r\n								</td>\r\n							</tr>\r\n						</table>\r\n						\r\n                        <br />\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </center>\r\n    </body>\r\n</html>', 'N', 'N', '#333333', 0, '2023-12-21 10:06:21', '2023-12-21 10:06:21'),
(11, 'Creator', 'creator', 'Y', 'paste', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"https://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n<html xmlns=\"https://www.w3.org/1999/xhtml\">\n<head><!-- If you delete this tag, the sky will fall on your head --><meta name=\"viewport\" content=\"width=device-width\" /><meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\" />\n	<title>Creator</title>\n	<style type=\"text/css\">/* ------------------------------------- \n		GLOBAL \n------------------------------------- */\n* { \n	margin:0;\n	padding:0;\n}\n* { font-family: \"Helvetica Neue\", \"Helvetica\", Helvetica, Arial, sans-serif; }\n\nimg { \n	max-width: 100%; \n}\n.collapse {\n	margin:0;\n	padding:0;\n}\nbody {\n	-webkit-font-smoothing:antialiased; \n	-webkit-text-size-adjust:none; \n	width: 100%!important; \n	height: 100%;\n}\n\n\n/* ------------------------------------- \n		ELEMENTS \n------------------------------------- */\na { color: #2BA6CB;}\n\ncode {\n	font-family: Courier, \'New Courier\', monospace;\n}\n\n.btn {\n	text-decoration:none;\n	color: #FFF;\n	background-color: #666;\n	padding:10px 16px;\n	font-weight:bold;\n	margin-right:10px;\n	text-align:center;\n	cursor:pointer;\n	display: inline-block;\n}\n\np.callout {\n	padding:15px;\n	background-color:#ECF8FF;\n	margin-bottom: 15px;\n}\n.callout a {\n	font-weight:bold;\n	color: #2BA6CB;\n}\n\ntable.social {\n/* 	padding:15px; */\n	background-color: #ebebeb;\n	\n}\n.social .soc-btn {\n	padding: 3px 7px;\n	font-size:12px;\n	margin-bottom:10px;\n	text-decoration:none;\n	color: #FFF;font-weight:bold;\n	display:block;\n	text-align:center;\n}\na.fb { background-color: #3B5998!important; }\na.tw { background-color: #1daced!important; }\na.gp { background-color: #DB4A39!important; }\na.ms { background-color: #000!important; }\n\n.sidebar .soc-btn { \n	display:block;\n	width:100%;\n}\n\n/* ------------------------------------- \n		HEADER \n------------------------------------- */\ntable.head-wrap { width: 100%;}\n\n.header.container table td.logo { padding: 15px; }\n.header.container table td.label { padding: 15px; padding-left:0px;}\n\n\n/* ------------------------------------- \n		BODY \n------------------------------------- */\ntable.body-wrap { width: 100%;}\n\n\n/* ------------------------------------- \n		FOOTER \n------------------------------------- */\ntable.footer-wrap { width: 100%;	clear:both!important;\n}\n.footer-wrap .container td.content  p { border-top: 1px solid rgb(215,215,215); padding-top:15px;}\n.footer-wrap .container td.content p {\n	font-size:10px;\n	font-weight: bold;\n	\n}\n\n\n/* ------------------------------------- \n		TYPOGRAPHY \n------------------------------------- */\nh1,h2,h3,h4,h5,h6 {\nfont-family: \"HelveticaNeue-Light\", \"Helvetica Neue Light\", \"Helvetica Neue\", Helvetica, Arial, \"Lucida Grande\", sans-serif; line-height: 1.1; margin-bottom:15px; color:#000;\n}\nh1 small, h2 small, h3 small, h4 small, h5 small, h6 small { font-size: 60%; color: #6f6f6f; line-height: 0; text-transform: none; }\n\nh1 { font-weight:200; font-size: 44px;}\nh2 { font-weight:200; font-size: 37px;}\nh3 { font-weight:500; font-size: 27px;}\nh4 { font-weight:500; font-size: 23px;}\nh5 { font-weight:900; font-size: 17px;}\nh6 { font-weight:900; font-size: 14px; text-transform: uppercase; color:#444;}\n\n.collapse { margin:0!important;}\n\np, ul { \n	margin-bottom: 10px; \n	font-weight: normal; \n	font-size:14px; \n	line-height:1.6;\n}\np.lead { font-size:17px; }\np.last { margin-bottom:0px;}\n\nul li {\n	margin-left:5px;\n	list-style-position: inside;\n}\n\n/* ------------------------------------- \n		SIDEBAR \n------------------------------------- */\nul.sidebar {\n	background:#ebebeb;\n	display:block;\n	list-style-type: none;\n}\nul.sidebar li { display: block; margin:0;}\nul.sidebar li a {\n	text-decoration:none;\n	color: #666;\n	padding:10px 16px;\n/* 	font-weight:bold; */\n	margin-right:10px;\n/* 	text-align:center; */\n	cursor:pointer;\n	border-bottom: 1px solid #777777;\n	border-top: 1px solid #FFFFFF;\n	display:block;\n	margin:0;\n}\nul.sidebar li a.last { border-bottom-width:0px;}\nul.sidebar li a h1,ul.sidebar li a h2,ul.sidebar li a h3,ul.sidebar li a h4,ul.sidebar li a h5,ul.sidebar li a h6,ul.sidebar li a p { margin-bottom:0!important;}\n\n\n\n/* --------------------------------------------------- \n		RESPONSIVENESS\n		Nuke it from orbit. It\'s the only way to be sure. \n------------------------------------------------------ */\n\n/* Set a max-width, and make it display as block so it will automatically stretch to that width, but will also shrink down on a phone or something */\n.container {\n	display:block!important;\n	max-width:600px!important;\n	margin:0 auto!important; /* makes it centered */\n	clear:both!important;\n}\n\n/* This should also be a block element, so that it will fill 100% of the .container */\n.content {\n	padding:15px;\n	max-width:600px;\n	margin:0 auto;\n	display:block; \n}\n\n/* Let\'s make sure tables in the content area are 100% wide */\n.content table { width: 100%; }\n\n\n/* Odds and ends */\n.column {\n	width: 300px;\n	float:left;\n}\n.column tr td { padding: 15px; }\n.column-wrap { \n	padding:0!important; \n	margin:0 auto; \n	max-width:600px!important;\n}\n.column table { width:100%;}\n.social .column {\n	width: 280px;\n	min-width: 279px;\n	float:left;\n}\n\n/* Be sure to place a .clear element after each set of columns, just to be safe */\n.clear { display: block; clear: both; }\n\n\n/* ------------------------------------------- \n		PHONE\n		For clients that support media queries.\n		Nothing fancy. \n-------------------------------------------- */\n@media only screen and (max-width: 600px) {\n	\n	a[class=\"btn\"] { display:block!important; margin-bottom:10px!important; background-image:none!important; margin-right:0!important;}\n\n	div[class=\"column\"] { width: auto!important; float:none!important;}\n	\n	table.social div[class=\"column\"] {\n		width:auto!important;\n	}\n\n}\n\n\n\n	@media screen and (max-width: 768px) {\n		img {max-width:  100% !important; height:  auto; }\n		.padded {padding-left:  10px; padding-right: 10px;}\n		.nav-inner td {\n			display: inline-block;\n		}\n	}\n\n	@media screen and (max-width: 320px) {\n		.inner {padding-left: 0px !important;padding-right: 0px !important;}\n\n	}\n\n	@media screen and (max-width: 600px) {\n		table.social > tbody > tr > td {\n			display: block;\n		}\n		.content {padding: 15px 0;}\n	}\n\n	</style>\n</head>\n<body bgcolor=\"#FFFFFF\" style=\"cursor: auto;\"><!-- HEADER -->\n\n[newsletters_track]\n\n<table bgcolor=\"#999999\" class=\"head-wrap\">\n	<tbody>\n		<tr>\n			<td>&nbsp;</td>\n			<td class=\"header container\">\n			<div class=\"content\">\n			<table bgcolor=\"#999999\">\n				<tbody>\n					<tr>\n						<td><img alt=\"\" src=\"https://placehold.it/200x50/\" /></td>\n						<td align=\"right\">\n						<h6 class=\"collapse\">CATCHY SLOGAN HERE</h6>\n						</td>\n					</tr>\n				</tbody>\n			</table>\n			</div>\n			</td>\n			<td>&nbsp;</td>\n		</tr>\n	</tbody>\n</table>\n<!-- /HEADER --><!-- BODY -->\n\n<table class=\"body-wrap\">\n	<tbody>\n		<tr>\n			<td>&nbsp;</td>\n			<td bgcolor=\"#FFFFFF\" class=\"container\">\n			<div class=\"content\">\n			<table>\n				<tbody>\n					<tr>\n						<td>\n						<h3>[newsletters_subject]</h3>\n\n						<p class=\"lead\">Put an introduction or summary of your newsletter here. Entice your readers to continue reading the rest of the newsletter.</p>\n						<!-- A Real Hero (and a real human being) -->\n\n						<p><img alt=\"\" src=\"https://placehold.it/600x300\" /></p>\n						<!-- /hero --><!-- Callout Panel -->\n\n						<p class=\"callout\">A call to action or business highlight goes here for your readers to click on. Link to a product,&nbsp;new service or limited offer you have right now. <a href=\"#\">Do it Now! »</a></p>\n						<!-- /Callout Panel -->\n\n						<div>[newsletters_main_content]</div>\n						\n						<p>The shortcode above is replaced with the content that you type into the editor. Use headings, paragraphs and other formatting in your newsletters to make them beautiful. Below is an example of how you can create beautiful newsletters. Use class <code>.btn</code> on any link to style it as a button.</p>\n\n						<h3>Title Ipsum <small>This is a note.</small></h3>\n\n						<p>Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.</p>\n						<a class=\"btn\">Click Me!</a><br />\n						<br />\n						<!-- social & contact -->\n						<table class=\"social\" width=\"100%\">\n							<tbody>\n								<tr>\n									<td><!--- column 1 -->\n									<table align=\"left\" class=\"column\">\n										<tbody>\n											<tr>\n												<td>\n												<h5>Connect with Us:</h5>\n\n												<p><a class=\"soc-btn fb\" href=\"#\">Facebook</a> <a class=\"soc-btn tw\" href=\"#\">Twitter</a> <a class=\"soc-btn gp\" href=\"#\">Google+</a></p>\n												</td>\n											</tr>\n										</tbody>\n									</table>\n									<!-- /column 1 --></td>\n									<td><!--- column 2 -->\n									<table align=\"left\" class=\"column\">\n										<tbody>\n											<tr>\n												<td>\n												<h5>Contact Info:</h5>\n\n												<p>Phone: <strong>123.456.0600</strong><br />\n												Email: <strong><a href=\"emailto:email@domain.com\">email@domain.com</a></strong></p>\n												</td>\n											</tr>\n										</tbody>\n									</table>\n									<!-- /column 2 --></td>\n								</tr>\n							</tbody>\n						</table>\n						<!-- /social & contact --></td>\n					</tr>\n				</tbody>\n			</table>\n			</div>\n			</td>\n			<td>&nbsp;</td>\n		</tr>\n	</tbody>\n</table>\n<!-- /BODY --><!-- FOOTER -->\n\n<table class=\"footer-wrap\">\n	<tbody>\n		<tr>\n			<td>&nbsp;</td>\n			<td class=\"container\"><!-- content -->\n			<div class=\"content\">\n			<table>\n				<tbody>\n					<tr>\n						<td align=\"center\">\n						<p><a href=\"#\">Terms</a> | <a href=\"#\">Privacy</a> | <a href=\"[newsletters_unsubscribeurl]\"><unsubscribe>Unsubscribe</unsubscribe></a></p>\n						</td>\n					</tr>\n				</tbody>\n			</table>\n			</div>\n			<!-- /content --></td>\n			<td>&nbsp;</td>\n		</tr>\n	</tbody>\n</table>\n<!-- /FOOTER --></body>\n</html>\n', 'N', 'N', '#333333', 0, '2023-12-21 10:06:21', '2023-12-21 10:06:21');
